 18	/*
 19	 * Attempt to restore the FPU registers directly from user memory.
 20	 * Pagefaults are handled and any errors returned are fatal.
 21	 */
 22	static int restore_fpregs_from_user(void __user *buf, u64 xrestore,
 23					    bool fx_only, unsigned int size)
 24	{
 25		struct fpu *fpu = &current->thread.fpu;
 26		int ret;
 27	
 28	retry:
 29		fpregs_lock();
 30		pagefault_disable();
 31		ret = __restore_fpregs_from_user(buf, xrestore, fx_only);
 32		pagefault_enable();
 33	
 34		if (unlikely(ret)) {
 35			/*
 36			 * The above did an FPU restore operation, restricted to
 37			 * the user portion of the registers, and failed, but the
 38			 * microcode might have modified the FPU registers
 39			 * nevertheless.
 40			 *
 41			 * If the FPU registers do not belong to current, then
 42			 * invalidate the FPU register state otherwise the task
 43			 * might preempt current and return to user space with
 44			 * corrupted FPU registers.
 45			 */
 46			if (test_thread_flag(TIF_NEED_FPU_LOAD))
 47				__cpu_invalidate_fpregs_state();
 48			fpregs_unlock();
 49	
 50			/* Try to handle #PF, but anything else is fatal. */
 51			if (ret != -EFAULT)
 52				return -EINVAL;
 53	
 54			if (!fault_in_readable(buf, size))
 55				goto retry;
 56			return -EFAULT;
 57		}
 58	
 59		/*
 60		 * Restore supervisor states: previous context switch etc has done
 61		 * XSAVES and saved the supervisor states in the kernel buffer from
 62		 * which they can be restored now.
 63		 *
 64		 * It would be optimal to handle this with a single XRSTORS, but
 65		 * this does not work because the rest of the FPU registers have
 66		 * been restored from a user buffer directly.
 67		 */
 68		if (test_thread_flag(TIF_NEED_FPU_LOAD) && xfeatures_mask_supervisor())
 69			os_xrstor(&fpu->state.xsave, xfeatures_mask_supervisor());
 70	
 71		fpregs_mark_activate();
 72		fpregs_unlock();
 73		return 0;
 74	}
